export function getExportableCanonicalEntities(): CanonicalEntityContract[] {
  return Object.values(CANONICAL_CONTRACT_REGISTRY).filter(
    (c) => c.exportPolicy === 'tenant_export'
  );
}

export function getRestorableCanonicalEntities(): CanonicalEntityContract[] {
  return Object.values(CANONICAL_CONTRACT_REGISTRY).filter(
    (c) => c.restorePolicy === 'tenant_restore'
  );
}

export function getTopologicallySortedContracts(): CanonicalEntityContract[] {
  const contracts = Object.values(CANONICAL_CONTRACT_REGISTRY);
  const contractMap = new Map(contracts.map((c) => [c.canonicalName, c]));
  const visited = new Set<string>();
  const visiting = new Set<string>();
  const result: CanonicalEntityContract[] = [];

  function visit(name: string) {
    if (visited.has(name)) return;
    if (visiting.has(name)) {
      throw new Error(`CANONICAL_DEPENDENCY_CYCLE: ${name}`);
    }
    visiting.add(name);
    const contract = contractMap.get(name);
    if (contract) {
      for (const dep of contract.dependencies) {
        if (contractMap.has(dep)) visit(dep);
      }
      visited.add(name);
      result.push(contract);
    }
    visiting.delete(name);
  }

  for (const contract of contracts) {
    if (!visited.has(contract.canonicalName)) {
      visit(contract.canonicalName);
    }
  }

  return result;
}